<?php
$active_menu='notices';$active_submenu='manage_notices';include 'header.php';require_once __DIR__.'/../notices.php';oecrm_require_permission($conn,'notices','view');oecrm_notice_sync_statuses($conn);$companyId=oecrm_current_company_id($conn);$editId=(int)($_GET['edit']??0);$edit=null;$selectedTargets=[];if($editId){$s=mysqli_prepare($conn,'SELECT * FROM notices WHERE id=? AND company_id=?');mysqli_stmt_bind_param($s,'ii',$editId,$companyId);mysqli_stmt_execute($s);$edit=mysqli_fetch_assoc(mysqli_stmt_get_result($s));mysqli_stmt_close($s);$tr=mysqli_query($conn,'SELECT department_id,employee_id FROM notice_targets WHERE notice_id='.(int)$editId);while($x=mysqli_fetch_assoc($tr))$selectedTargets[]=(int)($x['department_id']?:$x['employee_id']);}$departments=mysqli_query($conn,'SELECT id,name FROM departments WHERE company_id='.(int)$companyId.' AND status=1 ORDER BY name');$employees=mysqli_query($conn,'SELECT id,employeeCode,name,department_id FROM employeestbl WHERE company_id='.(int)$companyId.' AND status=0 ORDER BY name');$list=mysqli_query($conn,"SELECT n.*,(SELECT COUNT(*) FROM notice_receipts r WHERE r.notice_id=n.id AND r.read_at IS NOT NULL) read_count,(SELECT COUNT(*) FROM notice_receipts r WHERE r.notice_id=n.id AND r.acknowledged_at IS NOT NULL) ack_count,(SELECT COUNT(*) FROM notice_events ev WHERE ev.notice_id=n.id AND ev.event_type='view') view_count FROM notices n WHERE n.company_id=".(int)$companyId.' ORDER BY n.id DESC LIMIT 300');$flash=$_SESSION['notice_flash']??'';$error=$_SESSION['notice_error']??'';unset($_SESSION['notice_flash'],$_SESSION['notice_error']);
?>
<div id="page-wrapper" class="compact-admin-page notice-admin-page"><?php if($flash):?><div class="alert alert-success"><?php echo oecrm_h($flash);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo oecrm_h($error);?></div><?php endif;?><div class="panel panel-default"><div class="panel-heading foundation-heading"><span><?php echo $edit?'Edit':'Create';?> Notice</span><small>Schedule targeted announcements and track employee acknowledgement</small></div><div class="panel-body"><form method="post" action="noticeAction.php" enctype="multipart/form-data" class="notice-form"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0);?>"><div class="notice-form-grid four"><div class="form-group"><label>Notice Type</label><select name="notice_type" class="form-control"><?php foreach(['company','hr','policy','holiday'] as $v):?><option value="<?php echo $v;?>" <?php echo ($edit['notice_type']??'company')===$v?'selected':'';?>><?php echo ucfirst($v);?> Notice</option><?php endforeach;?></select></div><div class="form-group"><label>Priority</label><select name="priority" class="form-control"><?php foreach(['low','normal','high','urgent'] as $v):?><option value="<?php echo $v;?>" <?php echo ($edit['priority']??'normal')===$v?'selected':'';?>><?php echo ucfirst($v);?></option><?php endforeach;?></select></div><div class="form-group"><label>Publish At</label><input type="datetime-local" name="publish_at" class="form-control" required value="<?php echo oecrm_h(!empty($edit['publish_at'])?date('Y-m-d\TH:i',strtotime($edit['publish_at'])):date('Y-m-d\TH:i'));?>"></div><div class="form-group"><label>Expires At</label><input type="datetime-local" name="expires_at" class="form-control" value="<?php echo oecrm_h(!empty($edit['expires_at'])?date('Y-m-d\TH:i',strtotime($edit['expires_at'])):'');?>"></div></div><div class="form-group"><label>Title</label><input name="title" class="form-control" maxlength="180" required value="<?php echo oecrm_h($edit['title']??'');?>"></div><div class="form-group"><label>Notice Content</label><textarea name="body_html" class="form-control notice-editor" required><?php echo oecrm_h($edit['body_html']??'');?></textarea></div><div class="notice-form-grid"><div class="form-group"><label>Audience</label><select name="audience_type" id="noticeAudience" class="form-control"><?php foreach(['all'=>'All Employees','department'=>'Selected Departments','employee'=>'Selected Employees'] as $k=>$v):?><option value="<?php echo $k;?>" <?php echo ($edit['audience_type']??'all')===$k?'selected':'';?>><?php echo $v;?></option><?php endforeach;?></select></div><div class="form-group"><label>Attachment</label><input type="file" name="attachment" class="form-control" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png,.xls,.xlsx"><?php if(!empty($edit['attachment_original_name'])):?><small>Current: <?php echo oecrm_h($edit['attachment_original_name']);?></small><?php endif;?></div></div><div id="departmentTargets" class="notice-targets"><label>Departments</label><div><?php while($d=mysqli_fetch_assoc($departments)):?><label><input type="checkbox" name="department_ids[]" value="<?php echo (int)$d['id'];?>" <?php echo in_array((int)$d['id'],$selectedTargets,true)?'checked':'';?>> <?php echo oecrm_h($d['name']);?></label><?php endwhile;?></div></div><div id="employeeTargets" class="notice-targets"><label>Employees</label><div><?php while($e=mysqli_fetch_assoc($employees)):?><label><input type="checkbox" name="employee_ids[]" value="<?php echo (int)$e['id'];?>" <?php echo in_array((int)$e['id'],$selectedTargets,true)?'checked':'';?>> <?php echo oecrm_h($e['employeeCode'].' - '.$e['name']);?></label><?php endwhile;?></div></div><div class="notice-options"><label><input type="checkbox" name="show_popup" <?php echo !empty($edit['show_popup'])?'checked':'';?>> Dashboard popup</label><label><input type="checkbox" name="acknowledgement_required" <?php echo !empty($edit['acknowledgement_required'])?'checked':'';?>> Require acknowledgement</label></div><div class="foundation-actions"><button name="save_mode" value="draft" class="btn btn-default"><i class="fa fa-save"></i> Save Draft</button><button name="save_mode" value="publish" class="btn btn-primary"><i class="fa fa-bullhorn"></i> Publish / Schedule</button></div></form></div></div><div class="panel panel-default"><div class="panel-heading">Notice Delivery & History</div><div class="panel-body table-responsive"><table class="table foundation-table"><thead><tr><th>Notice</th><th>Audience</th><th>Schedule</th><th>Status</th><th>Engagement</th><th>Actions</th></tr></thead><tbody><?php if(mysqli_num_rows($list)===0):?><tr><td colspan="6" class="empty-cell">No notices created.</td></tr><?php endif;?><?php while($n=mysqli_fetch_assoc($list)):?><tr><td><span class="notice-priority <?php echo $n['priority'];?>"><?php echo ucfirst($n['priority']);?></span><strong><?php echo oecrm_h($n['title']);?></strong><small><?php echo oecrm_h(ucfirst($n['notice_type']).' notice');?></small></td><td><?php echo oecrm_h(ucfirst($n['audience_type']));?></td><td><?php echo date('d M Y h:i A',strtotime($n['publish_at']));?><small><?php echo $n['expires_at']?'Until '.date('d M Y',strtotime($n['expires_at'])):'No expiry';?></small></td><td><span class="notice-status <?php echo $n['status'];?>"><?php echo ucfirst($n['status']);?></span></td><td><strong><?php echo (int)$n['read_count'];?> read</strong><small><?php echo (int)$n['ack_count'];?> acknowledged, <?php echo (int)$n['view_count'];?> views</small></td><td class="notice-actions"><a class="icon-action" href="manageNotice.php?edit=<?php echo (int)$n['id'];?>" title="Edit"><i class="fa fa-pencil"></i></a><a class="icon-action" href="noticeReport.php?id=<?php echo (int)$n['id'];?>" title="Delivery Report"><i class="fa fa-bar-chart"></i></a><?php if($n['attachment_stored_name']):?><a class="icon-action" href="noticeAttachment.php?id=<?php echo (int)$n['id'];?>" title="Attachment"><i class="fa fa-paperclip"></i></a><?php endif;?><?php if(!in_array($n['status'],['cancelled','expired'],true)):?><form method="post" action="noticeAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?php echo (int)$n['id'];?>"><button class="icon-action danger" title="Cancel"><i class="fa fa-ban"></i></button></form><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div></div><script>(function(){var a=document.getElementById('noticeAudience'),d=document.getElementById('departmentTargets'),e=document.getElementById('employeeTargets');function sync(){d.style.display=a.value==='department'?'block':'none';e.style.display=a.value==='employee'?'block':'none';}a.addEventListener('change',sync);sync();})();</script></div><?php include 'footer.php';?>
